// Decodes web/fixtures (generated by `go test ./internal/v3/core/wire -run TestFixtures -update`)
// and checks the values in expected.json. Run with `npm test` (node --test, native type stripping).
// Excluded from tsc (tsconfig.json) because it uses Node APIs.

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { decodeMoverWindow, decodePalette, decodeTile, decodeTileDelta, pixelColor, rgb565ToRgb } from "./wire.ts";
import { chunkTile, datastoreId, escapeName, parseDatastoreId, surfaceId, tileAt, tileOrigin, tilePixelIndex, unescapeName, validTile } from "./grid.ts";

const dir = new URL("../../fixtures/", import.meta.url);
const bin = (name: string): Uint8Array => new Uint8Array(readFileSync(new URL(name, dir)));
const json = (name: string): any => JSON.parse(readFileSync(new URL(name, dir), "utf8"));
const expected = json("expected.json");

test("palette", () => {
  const pal = decodePalette(bin("palette.bin"));
  assert.equal(pal.length, expected["palette.bin"].count);
  assert.deepEqual(Array.from(pal), expected["palette.bin"].colors);
});

test("tiles", () => {
  const pal = decodePalette(bin("palette.bin"));
  const names = Object.keys(expected).filter(n => n.startsWith("tile_"));
  assert.ok(names.length >= 5, "tile fixtures present");
  for (const name of names) {
    const want = expected[name];
    const tile = decodeTile(bin(name));
    const h = tile.header;
    assert.deepEqual(
      [h.format, h.z, h.x, h.y, h.version, h.live, h.paletteVersion],
      [want.format, want.z, want.x, want.y, want.version, want.live, want.palette_version],
      `${name} header`,
    );
    for (const [px, py, rgb] of want.probes as number[][]) {
      assert.equal(pixelColor(tile.pixels, h.format, py * 512 + px, pal), rgb, `${name} pixel ${px},${py}`);
    }
  }
});

test("tile delta", () => {
  const pal = decodePalette(bin("palette.bin"));
  const want = expected["tiledelta_0_0_1-2.bin"];
  const d = decodeTileDelta(bin("tiledelta_0_0_1-2.bin"));
  const h = d.header;
  assert.deepEqual([h.format, h.x, h.y, h.from, h.to, h.paletteVersion, h.count], [want.format, want.x, want.y, want.from, want.to, want.palette_version, want.count]);
  assert.deepEqual(d.entries.map(e => e.block), want.blocks);
  for (const [entry, pos, rgb] of want.probes as number[][]) {
    assert.equal(pixelColor(d.entries[entry].pixels, h.format, pos, pal), rgb);
  }
  // Applying the delta to version 1 gives version 2.
  const v1 = decodeTile(bin("tile_z0_0_0_v1.bin"));
  const v2 = decodeTile(bin("tile_z0_0_0_v2.bin"));
  const patched = Uint16Array.from(v1.pixels, (_, i) => pixelColor(v1.pixels, v1.header.format, i, pal));
  for (const e of d.entries) {
    for (let p = 0; p < 1024; p++) {
      patched[tilePixelIndex(e.block, p)] = pixelColor(e.pixels, h.format, p, pal);
    }
  }
  for (let i = 0; i < patched.length; i++) {
    if (patched[i] !== pixelColor(v2.pixels, v2.header.format, i, pal)) {
      assert.fail(`patched pixel ${i} differs from version 2`);
    }
  }
});

test("mover windows", () => {
  for (const name of ["movers_window.bin", "movers_keyframe.bin", "movers_live.bin"]) {
    const want = expected[name];
    const w = decodeMoverWindow(bin(name));
    assert.equal(w.kind, want.kind, name);
    assert.equal(w.start, want.start, name);
    assert.equal(w.len, want.len, name);
    assert.deepEqual(w.movers.map(m => m.id), want.movers, name);
    assert.equal(w.rows.length, want.rows, name);
    const norm = (r: any) => ({ mover: r.mover, t: r.t, tick: r.tick, x: r.x, y: r.y, o: r.o, flags: r.flags, carriages: r.carriages ?? null });
    assert.deepEqual(norm(w.rows[0]), norm(want.first), `${name} first row`);
    assert.deepEqual(norm(w.rows[w.rows.length - 1]), norm(want.last), `${name} last row`);
    const flagged = w.rows.filter(r => r.flags !== 0 || r.carriages);
    assert.deepEqual(flagged.map(norm), (want.flagged ?? []).map(norm), `${name} flagged rows`);
  }
});

test("mover windows with rail path rows", () => {
  const want = expected["movers_rail.bin"];
  const w = decodeMoverWindow(bin("movers_rail.bin"));
  assert.equal(w.rows.length, want.rows);
  for (const [i, r] of w.rows.entries()) {
    const x = want.flagged[i]; // every row has the rail flag
    assert.equal(r.flags, x.flags, `row ${i} flags`);
    assert.equal(r.speed, x.speed, `row ${i} speed`);
    assert.equal(r.railStart, x.rail_start, `row ${i} rail start`);
    assert.deepEqual((r.rail ?? []).map(p => [p.x, p.y, p.dir, p.kind]), x.rail, `row ${i} pieces`);
  }
});

test("json fixtures have the documented shapes", () => {
  const cat = json("catalog.json");
  assert.equal(cat.version, 1);
  const ds = cat.maps[0].surfaces[0].datastores[0];
  assert.equal(ds.id, datastoreId({ map: cat.maps[0].key, surface: cat.maps[0].surfaces[0].name, force: ds.force }));
  assert.equal(cat.maps[0].surfaces[0].id, surfaceId({ map: cat.maps[0].key, surface: "nauvis" }));
  const view = json("view_z0.json");
  assert.equal(view.ds, ds.id);
  assert.ok(view.tiles.every((t: any) => typeof t.v === "number"));
  const timeline = json("timeline_z0.json");
  assert.ok(timeline.tiles.every((t: any) => Array.isArray(t.points)));
  const day = json("movers_day.json");
  assert.equal(day.windows[0].rows, expected["movers_window.bin"].rows);
  const ov = json("overlays_0_0.json");
  assert.deepEqual(ov.intervals.map((i: any) => i.kind), ["rail", "recipe", "tag", "tag"]);
  const lines = readFileSync(new URL("envelopes.ndjson", dir), "utf8").trim().split("\n");
  for (const line of lines) {
    const env = JSON.parse(line);
    assert.equal(env.v, 1);
    assert.ok(Array.isArray(env.msgs) && env.msgs.every((m: any) => typeof m.type === "string"));
  }
});

test("rgb565 expansion", () => {
  assert.deepEqual(rgb565ToRgb(0xffff), [255, 255, 255]);
  assert.deepEqual(rgb565ToRgb(0xf8c3), [255, 24, 24]);
});

test("grid and ids", () => {
  assert.deepEqual(chunkTile(-8, -8), { tile: { z: 0, x: 0, y: 0 }, block: 0 });
  assert.deepEqual(chunkTile(7, 7), { tile: { z: 0, x: 0, y: 0 }, block: 255 });
  assert.deepEqual(chunkTile(-9, 8), { tile: { z: 0, x: -1, y: 1 }, block: 15 });
  assert.deepEqual(tileAt(793, 567, -1), { z: -1, x: 1, y: 0 });
  assert.deepEqual(tileOrigin({ z: -2, x: 1, y: -1 }), [-256 + 2048, -256 - 2048]);
  assert.equal(tilePixelIndex(17, 33), 33 * 512 + 33);
  assert.ok(validTile({ z: 0, x: 2048, y: -2048 }) && !validTile({ z: 0, x: 2049, y: 0 }) && !validTile({ z: 1, x: 0, y: 0 }));
  assert.equal(escapeName("gw-bc41437d.1"), "gw-bc41437d~2E1");
  assert.equal(escapeName("Platform 1"), "~50latform~201");
  assert.equal(escapeName("é"), "~C3~A9");
  assert.equal(unescapeName("~C3~A9"), "é");
  assert.throws(() => unescapeName("~2e"));
  assert.deepEqual(parseDatastoreId("gw-bc41437d~2E1.nauvis.player"), { map: "gw-bc41437d.1", surface: "nauvis", force: "player" });
});
